 19	// Reuse the existing checked prod / pr-N / dev_identity stage owner. Invalid
 20	// stages fail before the native secret provider can request any credentials.
 21	export const nativeAppsDopplerSelection = Effect.fnUntraced(function* (
 22	  stage: string
 23	) {
 24	  const checked = yield* nativeAppsStage(stage).pipe(
 25	    Effect.mapError(
 26	      () =>
 27	        new Config.ConfigError(
 28	          new ConfigProvider.SourceError({
 29	            message: "Native app stack stage is missing or invalid",
 30	          })
 31	        )
 32	    )
 33	  );
 34	  if (checked === "prod") {
 35	    return AppsDopplerSelection.make({ config: "prd", project: "taxkit" });
 36	  }
 37	  return AppsDopplerSelection.make({
 38	    config: checked.startsWith("pr-") ? "stg_preview" : "dev",
 39	    project: "taxkit",
 40	  });
 41	});
