 43	export const nativeAppsSecrets = (({ stage }: SecretsContext) => [
 44	  Layer.unwrap(
 45	    nativeAppsDopplerSelection(stage).pipe(
 46	      Effect.map((selection) => Doppler.Secrets(selection).layer)
 47	    )
 48	  ),
 49	  ConfigProvider.layerAdd(
 50	    nativeAppsStage(stage).pipe(
 51	      Effect.map((checked) => {
 52	        // This account's 7 October Worker inventory has no rate-limit
 53	        // namespaces. Reserve 10078 for Production and append each checked
 54	        // PR number for Preview; two stages must never share its counters.
 55	        if (checked === "prod") {
 56	          return ConfigProvider.fromUnknown({
 57	            CALCULATOR_RATE_NAMESPACE: "10078",
 58	          });
 59	        }
 60	        if (checked.startsWith("pr-")) {
 61	          return ConfigProvider.fromUnknown({
 62	            CALCULATOR_RATE_NAMESPACE: `10078${checked.slice(3)}`,
 63	          });
 64	        }
 65	        return ConfigProvider.fromUnknown({});
 66	      })
 67	    ),
 68	    { asPrimary: true }
 69	  ),
 70	  // Native Stack.secrets otherwise appends the shell as its highest priority.
 71	  // Credentials still come through the native provider's credential source;
 72	  // ambient application values cannot override the selected Doppler config.
 73	  Secrets.ProcessEnv({ disabled: true }),
 74	]) satisfies StackSecrets;
